describe('handle', () => {
  let baseConfig: ConnectorConfig
  let calls: RecordedCall[]

  beforeEach(() => {
    baseConfig = {
      githubWebhookSecret: 'test-secret',
      linearApiKey: 'test-linear-key',
      linearTeamId: 'TRIAGE_TEAM_UUID',
      linearBugLabelId: 'BUG_LABEL_UUID_IN_LINEAR',
    }
    calls = []
  })

  function makePayload(overrides: Partial<GitHubIssuePayload> = {}): GitHubIssuePayload {
    return {
      action: 'labeled',
      issue: {
        title: 'Test issue',
        body: 'Test body',
        user: { login: 'test-user' },
        labels: [{ name: 'bug' }],
        html_url: 'https://github.com/owner/repo/issues/1',
      },
      repository: { full_name: 'owner/repo' },
      ...overrides,
    }
  }

  function createFetch(handler: (call: RecordedCall) => Response) {
    const { fetch, calls: recordedCalls } = fakeFetch(handler)
    calls.push(...recordedCalls)
    return fetch
  }

  it('happy path creates Linear issue with correct GraphQL mutation and variables', async () => {
    const fetch = createFetch((call) => {
      expect(call.method).toBe('POST')
      expect(call.url).toBe('https://api.linear.app/graphql')
      expect(call.headers.get('authorization')).toBe('Bearer test-linear-key')
      expect(call.headers.get('content-type')).toBe('application/json')

      const body = call.json as { query: string; variables: { input: unknown } }
      expect(body.query).toContain('mutation IssueCreate')
      expect(body.query).toContain('issueCreate(input: $input)')
      expect(body.variables.input).toEqual({
        title: 'Test issue',
        description: 'Test body',
        teamId: 'TRIAGE_TEAM_UUID',
        labelIds: ['BUG_LABEL_UUID_IN_LINEAR'],
      })

      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const payload = makePayload()
    const result = await handle(payload, { ...baseConfig, fetch })

    expect(result.linearIssueId).toBe('abc123')
    expect(result.linearIssueIdentifier).toBe('TRIAGE-456')
    expect(result.linearIssueUrl).toBe('https://linear.app/triageteam/issue/TRIAGE-456/fix-login-button-alignment')
  })

  it('verifies GitHub webhook signature via X-Hub-Signature-256 header', async () => {
    let verified = false
    const fetch = createFetch((call) => {
      verified = true
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const payload = makePayload()
    const rawBody = JSON.stringify(payload)
    const secret = 'test-secret'
    const crypto = await import('node:crypto')
    const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBody).digest('hex')

    // The connector doesn't receive headers directly in this test setup,
    // but we verify the signature verification logic is called by checking
    // that an invalid signature throws
    const invalidConfig = { ...baseConfig, githubWebhookSecret: 'wrong-secret', fetch }
    await expect(handle(payload, invalidConfig)).rejects.toThrow('Invalid webhook signature')
  })

  it('maps GitHub issue fields to Linear issue input correctly', async () => {
    const fetch = createFetch((call) => {
      const body = call.json as { variables: { input: { title: string; description: string; teamId: string; labelIds: string[] } } }
      expect(body.variables.input.title).toBe('Fix login button alignment')
      expect(body.variables.input.description).toBe('The login button is misaligned on mobile screens. Needs CSS adjustment.')
      expect(body.variables.input.teamId).toBe('TRIAGE_TEAM_UUID')
      expect(body.variables.input.labelIds).toEqual(['BUG_LABEL_UUID_IN_LINEAR'])
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const payload = makePayload({
      issue: {
        title: 'Fix login button alignment',
        body: 'The login button is misaligned on mobile screens. Needs CSS adjustment.',
        user: { login: 'alice-dev' },
        labels: [{ name: 'bug' }],
        html_url: 'https://github.com/owner/repo/issues/42',
      },
    })

    await handle(payload, { ...baseConfig, fetch })
  })

  it('throws when required field issue.title is missing', async () => {
    const fetch = createFetch(() => jsonResponse(TARGET_ENDPOINTS[0].response))
    const payload = makePayload({ issue: { ...makePayload().issue, title: '' } })

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: issue.title')
  })

  it('throws when required field issue.user.login is missing', async () => {
    const fetch = createFetch(() => jsonResponse(TARGET_ENDPOINTS[0].response))
    const payload = makePayload({ issue: { ...makePayload().issue, user: { login: '' } } })

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: issue.user.login')
  })

  it('throws when required field issue.html_url is missing', async () => {
    const fetch = createFetch(() => jsonResponse(TARGET_ENDPOINTS[0].response))
    const payload = makePayload({ issue: { ...makePayload().issue, html_url: '' } })

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: issue.html_url')
  })

  it('throws when issue does not have bug label', async () => {
    const fetch = createFetch(() => jsonResponse(TARGET_ENDPOINTS[0].response))
    const payload = makePayload({ issue: { ...makePayload().issue, labels: [{ name: 'feature' }] } })

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Issue does not have the "bug" label')
  })

  it('throws on non-2xx response from Linear API', async () => {
    const fetch = createFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const payload = makePayload()

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Linear API error: 401 Unauthorized at POST https://api.linear.app/graphql'
    )
  })

  it('throws on Linear GraphQL errors', async () => {
    const fetch = createFetch(() =>
      jsonResponse({
        errors: [{ message: 'Variable $input of type IssueCreateInput! was provided invalid value' }],
      })
    )
    const payload = makePayload()

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Linear GraphQL errors: Variable $input of type IssueCreateInput! was provided invalid value'
    )
  })

  it('throws when Linear returns success false', async () => {
    const fetch = createFetch(() =>
      jsonResponse({
        data: { issueCreate: { success: false, issue: null } },
      })
    )
    const payload = makePayload()

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Linear issue creation failed: no issue returned')
  })

  it('only processes labeled or opened actions', async () => {
    const fetch = createFetch(() => jsonResponse(TARGET_ENDPOINTS[0].response))
    const payload = makePayload({ action: 'closed' })

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      "Unsupported action: closed. Only 'labeled' or 'opened' are processed."
